.ends SUB_1

* Stimulus
Vin N002 0 dc 0.9 ac 1 sin(0.9 10m 1k)

.control
  op
  print v(Vout) v(N003) v(N001)

  ac dec 100 1 1G
  let gain_db = vdb(Vout)
  let phase = 180/PI * cph(v(Vout))

  meas ac max_gain max gain_db
  let f3db_val = max_gain - 3
  meas ac f3db when gain_db=f3db_val fall=1

  tran 1u 5m
  meas tran vout_ptp pp v(Vout)

  quit
.endc

